<?php class DoctorController extends Controller{function index(){$db=Database::db();$sql='SELECT doctors.id,users.name,users.phone,specializations.name specialization,doctors.experience_years,doctors.bio,hospitals.name hospital,doctor_hospitals.consultation_fee,doctor_hospitals.video_fee,doctor_hospitals.emergency_fee,addresses.city,addresses.state FROM doctors JOIN users ON users.id=doctors.user_id LEFT JOIN specializations ON specializations.id=doctors.specialization_id LEFT JOIN doctor_hospitals ON doctor_hospitals.doctor_id=doctors.id AND doctor_hospitals.is_primary=1 LEFT JOIN hospitals ON hospitals.id=doctor_hospitals.hospital_id LEFT JOIN addresses ON addresses.user_id=users.id WHERE doctors.verification_status="approved"';$args=[];foreach(['city'=>'addresses.city','specialization'=>'specializations.name','hospital'=>'hospitals.name','doctor'=>'users.name'] as $k=>$col){if(!empty($_GET[$k])){$sql.=" AND $col LIKE ?";$args[]='%'.$_GET[$k].'%';}}$sql.=' ORDER BY users.name';$q=$db->prepare($sql);$q->execute($args);$this->view('doctors/index',['doctors'=>$q->fetchAll(PDO::FETCH_ASSOC)]);}}